<?php require 'config.php'; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($_POST['qty']??[] as $id=>$qty){$qty=max(0,min(99,(int)$qty));if($qty===0)unset($_SESSION['cart'][(int)$id]);else $_SESSION['cart'][(int)$id]=$qty;}redirect('cart.php');}$items=[];$subtotal=0;if(!empty($_SESSION['cart'])){$ids=array_keys($_SESSION['cart']);$marks=implode(',',array_fill(0,count($ids),'?'));$types=str_repeat('i',count($ids));$stmt=db()->prepare("SELECT * FROM products WHERE id IN ($marks) AND is_active=1");$stmt->bind_param($types,...$ids);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$row['qty']=$_SESSION['cart'][$row['id']];$row['line_total']=$row['qty']*$row['price'];$subtotal+=$row['line_total'];$items[]=$row;}}page_start('Your cart'); ?>
<section class="section-space"><div class="container"><div class="eyebrow">Your selection</div><h1 class="display-5 mb-5">Your cart.</h1><?php if(!$items): ?><div class="bg-white p-5 text-center rounded-3"><h2 class="h4">Your cart is waiting.</h2><p class="text-muted">Pick a resource and give your next project a head start.</p><a href="products.php" class="btn btn-dark btn-rounded">Browse the library</a></div><?php else: ?><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><div class="row g-5"><div class="col-lg-8"><?php foreach($items as $item): ?><div class="d-flex align-items-center gap-3 border-bottom py-3"><div class="product-art <?= e($item['cover_color']) ?> flex-shrink-0" style="width:90px;height:80px;font-size:.8rem;padding:.5rem"><?= e($item['title']) ?></div><div class="flex-grow-1"><h2 class="h6 mb-1"><?= e($item['title']) ?></h2><div class="text-muted small"><?= money((float)$item['price']) ?> each</div></div><input class="form-control" style="width:75px" type="number" min="0" max="99" name="qty[<?= $item['id'] ?>]" value="<?= $item['qty'] ?>"><strong><?= money((float)$item['line_total']) ?></strong></div><?php endforeach; ?><button class="btn btn-outline-dark btn-rounded mt-3">Update cart</button></div><div class="col-lg-4"><div class="bg-white p-4 rounded-3"><div class="d-flex justify-content-between mb-3"><span>Subtotal</span><strong><?= money((float)$subtotal) ?></strong></div><a href="checkout.php" class="btn btn-dark w-100 btn-rounded">Continue to checkout →</a></div></div></div></form><?php endif; ?></div></section><?php page_end(); ?>